        return 0
    return total(n - 1) + n


def solve(kind, nums):
    print(f"{kind} {nums}")
    if kind == "logic":
        p, q = bool(nums[0]), bool(nums[1])
        print(f"  p {p}, q {q}: not p {not p}, p and q {p and q}, p or q {p or q}")
        print(f"  p -> q is not p or q: {not p or q}")
    elif kind == "first-fail":
        lo, hi = nums[0], nums[1]
        first = "none"
        for x in range(lo, hi + 1):
            if not 2 ** x > x * x and first == "none":
                first = x
        print(f"  2^x > x^2 for every x from {lo} to {hi}: {all(2 ** x > x * x for x in range(lo, hi + 1))}")
        print(f"  first counterexample: {first}")
    elif kind == "venn":
        n, a, b = nums[0], nums[1], nums[2]
        U = set(range(1, n + 1))
        A = {x for x in U if x % a == 0}
        B = {x for x in U if x % b == 0}
        print(f"  A = {sorted(A)}, B = {sorted(B)}, A & B = {sorted(A & B)}")
        print(f"  |A | B| = {len(A)} + {len(B)} - {len(A & B)} = {len(A | B)}   inclusion-exclusion")
    elif kind == "classify":
        n, a, b, m = nums[0], nums[1], nums[2], nums[3]
        f = {x: (a * x + b) % m for x in range(n)}
        outs = set(f.values())
        print(f"  f = {f}")
        print(f"  one-to-one {len(outs) == len(f)}, onto {outs == set(range(m))}")
    elif kind == "parity":
        m, n = nums[0], nums[1]
        j, k = m // 2, n // 2
        if m % 2 == 1 and n % 2 == 1:
            print(f"  (2({j}) + 1) + (2({k}) + 1) = 2({j + k + 1}) = {m + n}, even")
        elif m % 2 == 0 and n % 2 == 0:
            print(f"  2({j}) + 2({k}) = 2({j + k}) = {m + n}, even")
        else:
            print(f"  one even, one odd: 2({j + k}) + 1 = {m + n}, odd")
    elif kind == "sum":
        n = nums[0]
        print(f"  total({n}) = total({n - 1}) + {n} = {total(n)}, formula {n} * {n + 1} / 2 = {n * (n + 1) // 2}")


