import math
from itertools import product


def solve(kind, nums):
    print(f"{kind} {nums}")
    if kind == "incl":
        n, a, b = nums[0], nums[1], nums[2]
        L = math.lcm(a, b)
        count = n // a + n // b - n // L
        print(f"  {n // a} + {n // b} - {n // L} = {count}   the overlap uses lcm {L}")
        print(f"  check by the set: {len({x for x in range(1, n + 1) if x % a == 0 or x % b == 0})}")
    elif kind == "invert":
        a, b, m, y = nums[0], nums[1], nums[2], nums[3]
        e = {x: (a * x + b) % m for x in range(m)}
        print(f"  e = {e}")
        if len(set(e.values())) == m:
            d = {v: k for k, v in e.items()}
            print(f"  a bijection, so flip it: d({y}) = {d[y]}, check e({d[y]}) = {e[d[y]]}")
        else:
            print("  outputs repeat, so not one-to-one and no inverse")
    elif kind == "contra":
        m = nums[0]
        bad, contra, first = 0, 0, "none"
        for n in range(1, 101):
            p, q = n * n % m == 0, n % m == 0
            if p and not q:
                bad = bad + 1
                if first == "none":
                    first = n
            contra = contra + (not q and not (not p))
        print(f"  if {m} | n^2 then {m} | n: {bad} counterexamples up to 100, first {first}")
        print(f"  the contrapositive fails {contra} times, the same")
    elif kind == "pigeon":
        p, n = nums[0], nums[1]
        total, one = 0, 0
        for outs in product(range(1, n + 1), repeat=p):
            total = total + 1
            one = one + (len(set(outs)) == p)
        print(f"  {total} functions, {one} one-to-one, shared hole forced: {p > n}")
    elif kind == "classes":
        n, m = nums[0], nums[1]
        top = m
        if n < m:
            top = n
        for a in range(1, top + 1):
            print(f"  [{a}] = {[x for x in range(1, n + 1) if (x - a) % m == 0]}")


solve("incl", [100, 4, 6])
solve("invert", [3, 2, 7, 5])
solve("invert", [2, 1, 6, 3])
solve("contra", [3])
solve("contra", [9])
solve("pigeon", [4, 3])
solve("pigeon", [2, 3])
solve("classes", [10, 4])

