import math


def smallest_factor(n):
    d = 2
    while d * d <= n:
        if n % d == 0:
            return d
        d = d + 1
    return n


def pay(n):
    if n == 8:
        return (1, 1)
    if n == 9:
        return (3, 0)
    if n == 10:
        return (0, 2)
    threes, fives = pay(n - 3)
    return (threes + 1, fives)


def solve(kind, nums):
    print(f"{kind} {nums}")
    if kind == "prime-formula":
        a, b = nums[0], nums[1]
        n = 0
        while n * n + a * n + b >= 2 and smallest_factor(n * n + a * n + b) == n * n + a * n + b:
            n = n + 1
        v = n * n + a * n + b
        if n == 0:
            print(f"  it fails at once: n = 0 gives {v}")
        else:
            print(f"  prime for n = 0 to {n - 1}, then n = {n} gives {v}")
        if v < 2:
            print(f"  {v} is below 2, so not prime")
        else:
            print(f"  {v} = {smallest_factor(v)} * {v // smallest_factor(v)}   a counterexample")
    elif kind == "solvable":
        a, b, c = nums[0], nums[1], nums[2]
        g = math.gcd(a, b)
        count = 0
        for m in range(-20, 21):
            for n in range(-20, 21):
                count = count + (a * m + b * n == c)
        print(f"  {a}m + {b}n = {g}({a // g}m + {b // g}n), so a solution needs {g} | {c}: {c % g == 0}")
        print(f"  solutions with m and n from -20 to 20: {count}")
    elif kind == "demorgan":
        n, a, b = nums[0], nums[1], nums[2]
        U = set(range(1, n + 1))
        A = {x for x in U if x % a == 0}
        B = {x for x in U if x % b == 0}
        print(f"  (A | B)c = {sorted(U - (A | B))}")
        print(f"  Ac & Bc equal: {U - (A | B) == (U - A) & (U - B)}, the trap Ac | Bc equal: {U - (A | B) == (U - A) | (U - B)}")
    elif kind == "pay":
        n = nums[0]
        if n < 8:
            print(f"  {n} is below 8, so the proof doesn't cover it")
        else:
            threes, fives = pay(n)
            print(f"  {n} = {threes} threes + {fives} fives = {3 * threes + 5 * fives}   base cases 8, 9, 10, step 3")


